package com.mockarena.question.application;
import com.mockarena.question.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class QuestionEvaluationDataService { private final QuestionVersionRepository versions; public QuestionEvaluationDataService(QuestionVersionRepository versions){this.versions=versions;} @Transactional(readOnly=true) public List<McqEvaluationData> resolve(List<UUID> ids){Map<UUID,QuestionVersion> found=new HashMap<>();versions.findAllById(ids).forEach(v->found.put(v.id(),v));return ids.stream().map(id->{QuestionVersion v=Optional.ofNullable(found.get(id)).orElseThrow(()->new NoSuchElementException("Question version not found"));if(v.status()!=QuestionVersionStatus.PUBLISHED&&v.status()!=QuestionVersionStatus.RETIRED)throw new NoSuchElementException("Question version not evaluable");return v.mcqEvaluationData();}).toList();}}
